from app.services.stats import progress_summary


def test_mixed_statuses_exact_counts():
    got = progress_summary(["todo", "done", "in_progress", "done"])
    assert got == {"total": 4, "todo": 1, "in_progress": 1, "done": 2, "percent_done": 50.0}


def test_all_done_is_100_percent():
    assert progress_summary(["done", "done"])["percent_done"] == 100.0


def test_empty_list_is_zero():
    got = progress_summary([])
    assert got["total"] == 0
    assert got["percent_done"] == 0.0


def test_in_progress_not_counted_as_done():
    got = progress_summary(["in_progress", "todo"])
    assert got["done"] == 0
    assert got["percent_done"] == 0.0

