from app.services.stats import progress_summary


def test_returns_dict():
    assert isinstance(progress_summary(["done"]), dict)


def test_total_counts():
    assert progress_summary(["todo", "done"])["total"] == 2


def test_empty_total():
    assert progress_summary([])["total"] == 0


def test_percent_in_range():
    assert 0 <= progress_summary(["done", "todo"])["percent_done"] <= 100
